def derangement_egf(n):    # e^{-x}/(1-x) 的原始系数 = 错排 D_n
  a = exp_series(n, -1)    # e^{-x}: 系数 (-1)^k
  b = [1]*n                # 1/(1-x): 系数 1
  return egf_mul_coeff(a, b)
